}

package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;

/**
 * 整体替换草稿占用清单请求，expectedVersion 必须与当前版本一致；
 * stationStops 同时被整体替换，operator 参与幂等指纹。
 */
public record UpdateOccupanciesRequest(
        @NotBlank String requestKey,
        @NotBlank String operator,
        @NotNull Integer expectedVersion,
        @NotNull @Size(min = 1, max = 30) List<@Valid OccupancyRequest> occupancies,
        @NotNull @Size(max = 30) List<@Valid StationStopRequest> stationStops) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 原子改签请求：将路径中的已发布旧计划取消，并发布同运营日的新草稿。
 * requestKey 为幂等键；operator 为操作者标识并参与幂等指纹；
 * 两个期望版本分别对旧、新计划做乐观校验。
 */
public record RescheduleRequest(
        @NotBlank String requestKey,
        @NotBlank String operator,
        @NotBlank String newScheduleKey,
        @NotNull Integer expectedOldVersion,
        @NotNull Integer expectedNewVersion) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 发布 / 取消计划请求，携带幂等键与操作者标识（操作者参与幂等指纹）。
 */
public record PlanActionRequest(@NotBlank String requestKey, @NotBlank String operator) {
}

package com.example.starter.plan.web.dto;

import java.time.LocalDate;
import java.util.List;

/**
 * 日计划响应，含当前状态、版本、占用清单与中间站登记（取消后历史原样返回）。
