                        rs.getInt("station_version"),
                        rs.getObject("arrival_utc") == null ? null
                                : Instant.ofEpochMilli(rs.getLong("arrival_utc")),
                        rs.getObject("departure_utc") == null ? null
                                : Instant.ofEpochMilli(rs.getLong("departure_utc")),
