    List<List<Object>> rows = new ArrayList<>(stops.size());
    for (StationStopRequest s : stops) {
        // 到发允许 null（始发/终到语义），List.of 不接受 null，故用 ArrayList
        List<Object> row = new ArrayList<>(4);
        row.add(s.trainNo());
